def longest_subarray(nums):
    # Find the maximum element in nums
    max_val = max(nums)
    max_len = 0
    cur_len = 0

    # Iterate through nums to find the longest contiguous block of max_val
    for num in nums:
        if num == max_val:
            cur_len += 1   # Increase current length
            if cur_len > max_len:
                max_len = cur_len
        else:
            cur_len = 0    # Reset if we hit a smaller value

    return max_len
